    // ---- terminals ----
    pub async fn get(&mut self) -> Result<BattleRow> { let row = self.get_or_none().await?; row.ok_or(orm::Error::NoRows) }

    pub async fn get_or_none(&mut self) -> Result<Option<BattleRow>> { let binding = self.binding.clone(); let ex = binding.resolve()?;
        let mut rows = db::select(ex, &mut self.q.req, "one").await?;
        Ok(match rows.take_cells().into_iter().next() {
            Some(mut src) => Some(BattleRow::from_row(&mut src, &rows.assemble, &rows)?),
            None => None,
        })
    }

    pub async fn gets(&mut self) -> Result<Collection<BattleRow>> { let binding = self.binding.clone(); let ex = binding.resolve()?;
        let mut rows = db::select(ex, &mut self.q.req, "all").await?;
        collect(&mut rows, self.key_fn.as_deref())
    }

    pub async fn gets_after(&mut self, cursor: &str, per: u32) -> Result<orm::KeysetPage<BattleRow>> {
        self.q.keyset("after", cursor, per, &["seq"])?;
        let binding = self.binding.clone(); let ex = binding.resolve()?;
        let mut rows = db::select(ex, &mut self.q.req, "all").await?;
        let (next_cursor, previous_cursor) = rows.keyset_cursors(&self.q.req.ir.query.order)?;
        let items = collect(&mut rows, self.key_fn.as_deref())?;
        Ok(orm::KeysetPage { items, next_cursor, previous_cursor })
    }

    pub async fn gets_before(&mut self, cursor: &str, per: u32) -> Result<orm::KeysetPage<BattleRow>> {
        self.q.keyset("before", cursor, per, &["seq"])?;
        let binding = self.binding.clone(); let ex = binding.resolve()?;
        let mut rows = db::select(ex, &mut self.q.req, "all").await?;
        rows.reverse_main();
        let (next_cursor, previous_cursor) = rows.keyset_cursors(&self.q.req.ir.query.order)?;
        let items = collect(&mut rows, self.key_fn.as_deref())?;
        Ok(orm::KeysetPage { items, next_cursor, previous_cursor })
    }

    /// Visits independently owned rows without accumulating the complete result.
    pub async fn stream(&mut self, visit: impl FnMut(BattleRow) -> bool) -> Result<db::StreamResult> {
        let mut visit = visit;
        let binding = self.binding.clone();
        let ex = binding.resolve()?;
        db::stream(ex, &mut self.q.req, |mut src, rows| {
            let row = BattleRow::from_row(&mut src, &rows.assemble, rows)?;
            Ok(visit(row))
        }).await
    }


